import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.B5WAEDB7.js";const a="/assets/images/h9TAuGI.jpg",f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/content-delivery-network.md","filePath":"core-concepts/content-delivery-network.md"}'),o={name:"core-concepts/content-delivery-network.md"};function s(l,e,c,d,h,u){return n(),r("div",null,[...e[0]||(e[0]=[i('<h2 id="content-delivery-network" tabindex="-1">Content delivery network <a class="header-anchor" href="#content-delivery-network" aria-label="Permalink to &quot;Content delivery network&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Content delivery network.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p align="center"><img src="'+a+'"><br><i><a href="https://www.creative-artworks.eu/why-use-a-content-delivery-network-cdn/">Source: Why use a CDN</a></i></p><p>A content delivery network (CDN) is a globally distributed network of proxy servers, serving content from locations closer to the user. Generally, static files such as HTML/CSS/JS, photos, and videos are served from CDN, although some CDNs such as Amazon&#39;s CloudFront support dynamic content. The site&#39;s DNS resolution will tell clients which server to contact.</p><p>Serving content from CDNs can significantly improve performance in two ways:</p><ul><li>Users receive content from data centers close to them</li><li>Your servers do not have to serve requests that the CDN fulfills</li></ul><h3 id="push-cdns" tabindex="-1">Push CDNs <a class="header-anchor" href="#push-cdns" aria-label="Permalink to &quot;Push CDNs&quot;">​</a></h3><p>Push CDNs receive new content whenever changes occur on your server. You take full responsibility for providing content, uploading directly to the CDN and rewriting URLs to point to the CDN. You can configure when content expires and when it is updated. Content is uploaded only when it is new or changed, minimizing traffic, but maximizing storage.</p><p>Sites with a small amount of traffic or sites with content that isn&#39;t often updated work well with push CDNs. Content is placed on the CDNs once, instead of being re-pulled at regular intervals.</p><h3 id="pull-cdns" tabindex="-1">Pull CDNs <a class="header-anchor" href="#pull-cdns" aria-label="Permalink to &quot;Pull CDNs&quot;">​</a></h3><p>Pull CDNs grab new content from your server when the first user requests the content. You leave the content on your server and rewrite URLs to point to the CDN. This results in a slower request until the content is cached on the CDN.</p><p>A <a href="https://en.wikipedia.org/wiki/Time_to_live" target="_blank" rel="noreferrer">time-to-live (TTL)</a> determines how long content is cached. Pull CDNs minimize storage space on the CDN, but can create redundant traffic if files expire and are pulled before they have actually changed.</p><p>Sites with heavy traffic work well with pull CDNs, as traffic is spread out more evenly with only recently-requested content remaining on the CDN.</p><h3 id="disadvantage-s-cdn" tabindex="-1">Disadvantage(s): CDN <a class="header-anchor" href="#disadvantage-s-cdn" aria-label="Permalink to &quot;Disadvantage(s): CDN&quot;">​</a></h3><ul><li>CDN costs could be significant depending on traffic, although this should be weighed with additional costs you would incur not using a CDN.</li><li>Content might be stale if it is updated before the TTL expires it.</li><li>CDNs require changing URLs for static content to point to the CDN.</li></ul><h3 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h3><ul><li><a href="https://figshare.com/articles/Globally_distributed_content_delivery/6605972" target="_blank" rel="noreferrer">Globally distributed content delivery</a></li><li><a href="https://www.geeksforgeeks.org/system-design/pull-cdn-vs-push-cdn/" target="_blank" rel="noreferrer">The differences between push and pull CDNs</a></li><li><a href="https://en.wikipedia.org/wiki/Content_delivery_network" target="_blank" rel="noreferrer">Wikipedia</a></li></ul>',17)])])}const w=t(o,[["render",s]]);export{f as __pageData,w as default};
